import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

/**
 * Moves the `@generated by permdock generate <kind>@<version>` headers of
 * committed generated files and gen snapshots from the committed `permdock`
 * version to the new one; `version-packages` runs it after `changeset version`,
 * so the Version PR passes `gen:check` and the gen snapshot tests.
 */
const root = new URL("../", import.meta.url);
const pkg: unknown = JSON.parse(
  readFileSync(new URL("packages/permdock/package.json", root), "utf8"),
);
if (
  typeof pkg !== "object" ||
  pkg === null ||
  !("version" in pkg) ||
  typeof pkg.version !== "string"
) {
  throw new Error("packages/permdock/package.json is malformed");
}
const { version } = pkg;
const committed: unknown = JSON.parse(
  execFileSync("git", ["show", "HEAD:packages/permdock/package.json"], {
    cwd: root,
    encoding: "utf8",
  }),
);
if (
  typeof committed !== "object" ||
  committed === null ||
  !("version" in committed) ||
  typeof committed.version !== "string"
) {
  throw new Error("HEAD:packages/permdock/package.json is malformed");
}
const header = new RegExp(
  `(generated by permdock generate [a-z-]+@)${committed.version.replaceAll(".", "\\.")}(?![0-9A-Za-z.+-])`,
  "gu",
);
const files = execFileSync(
  "git",
  ["grep", "-lE", "generated by permdock generate [a-z-]+@[0-9]"],
  { cwd: root, encoding: "utf8" },
)
  .split("\n")
  .filter((file) => file !== "");
for (const file of files) {
  const path = new URL(file, root);
  const text = readFileSync(path, "utf8");
  const next = text.replaceAll(header, `$1${version}`);
  if (next !== text) {
    writeFileSync(path, next);
  }
}
